CREATE OR REPLACE TRIGGER tr_productos_precio
BEFORE INSERT OR UPDATE OF precio ON productos
FOR EACH ROW
BEGIN
    IF :NEW.precio < 0 THEN
        RAISE_APPLICATION_ERROR(-20001, 'El precio no puede ser negativo');
    END IF;
END;
/

CREATE OR REPLACE PACKAGE tienda_pkg AS
    FUNCTION total_pedido (p_pedido_id NUMBER) RETURN NUMBER;
END;
/

CREATE OR REPLACE PACKAGE BODY tienda_pkg AS
    FUNCTION total_pedido (p_pedido_id NUMBER) RETURN NUMBER AS
        v_total NUMBER;
    BEGIN
        SELECT SUM(cantidad * precio_unitario) INTO v_total
        FROM pedido_productos WHERE pedido_id = p_pedido_id;
        RETURN NVL(v_total, 0);
    END;
END;
/
